-- ============================================================
-- DATOS HISTÓRICOS 2025
-- ============================================================

SET search_path TO transaccional, public;

-- Limpieza de datos previos de 2025 para idempotencia
DELETE FROM movimiento_caja WHERE caja_id IN (SELECT id FROM caja WHERE EXTRACT(YEAR FROM fecha_apertura) = 2025);
DELETE FROM detalle_venta WHERE venta_id IN (SELECT id FROM venta WHERE EXTRACT(YEAR FROM fecha) = 2025);
DELETE FROM venta WHERE EXTRACT(YEAR FROM fecha) = 2025;
DELETE FROM produccion WHERE EXTRACT(YEAR FROM fecha_produccion) = 2025;
DELETE FROM orden_produccion WHERE EXTRACT(YEAR FROM fecha_inicio) = 2025;
DELETE FROM gasto WHERE EXTRACT(YEAR FROM fecha) = 2025;
DELETE FROM caja WHERE EXTRACT(YEAR FROM fecha_apertura) = 2025;

