UPDATE caja SET estado='cerrada', fecha_cierre='2025-01-31', total_ingresos=(SELECT COALESCE(SUM(monto),0) FROM movimiento_caja WHERE caja_id=caja.id AND tipo='ingreso'), total_egresos=(SELECT COALESCE(SUM(monto),0) FROM movimiento_caja WHERE caja_id=caja.id AND tipo='egreso'), saldo_final=saldo_inicial + (SELECT COALESCE(SUM(monto),0) FROM movimiento_caja WHERE caja_id=caja.id AND tipo='ingreso') - (SELECT COALESCE(SUM(monto),0) FROM movimiento_caja WHERE caja_id=caja.id AND tipo='egreso') WHERE fecha_apertura='2025-01-01';

